      SUBROUTINE ACCGET          CC     SUBROUTINE ACCGET GETS THE PARAMETERS FOR AN ACCELERATOR ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM11.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM26B.CIN'                                   INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER         IADR, IDATA, IT      REAL            DATAR, FREQ      EXTERNAL        DATAR, IDATACC-------------------------------------------------------      IADR = I + 1      L = DATAR(IADR)      IF (PRAN11(1) .NE. 0.0) L = L + PRAN11(1)*XRAN(1)      L = L*UNITI(8)C      IADR = I + 2      EGAIN = DATAR(IADR)      IF (PRAN11(2) .NE. 0.0)     1    EGAIN = EGAIN + PRAN11(2)*XRAN(2)      EGAIN = EGAIN*UNITI(11)C      IADR = I + 3      PHASEL = DATAR(IADR)      IF (PRAN11(3) .NE. 0.0)     1    PHASEL = PHASEL + PRAN11(3)*XRAN(3)      PHASEL = PHASEL/RADIANC      IADR = I + 4      IF (IPTOJ(5) .EQ. 0) THEN        WAVEL = DATAR(IADR)        IF (PRAN11(4) .NE. 0.0)     1      WAVEL = WAVEL + PRAN11(4)*XRAN(4)        WAVEL = WAVEL*UNITI(5)      ELSE        FREQ = DATAR(IADR)        WAVEL = CLIGHT*1.0E-6/FREQ      ENDIF      IT = IPTOJ(6)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END